}$manifest212$::jsonb;
 v_catalog jsonb;v_object jsonb;v_actual jsonb;v_shape jsonb;v_acl jsonb;
 v_related jsonb;v_history jsonb;v_before jsonb:='{}'::jsonb;
 v_count integer;v_pass integer;v_section text;
BEGIN
 IF current_user <> 'postgres' THEN RAISE EXCEPTION 'OWNER_ACL212_POSTGRES_REQUIRED'; END IF;
 IF current_setting('server_version_num')::integer/10000 <> 17 THEN RAISE EXCEPTION 'OWNER_ACL212_POSTGRES17_REQUIRED'; END IF;
 IF NOT pg_try_advisory_xact_lock(734151139) THEN RAISE EXCEPTION 'OWNER_ACL212_UPGRADE_RUNNING'; END IF;
 FOR v_pass IN 1..2 LOOP
  SELECT coalesce(jsonb_agg(version::text ORDER BY version::text COLLATE "C"),'[]'::jsonb)
   INTO v_history FROM supabase_migrations.schema_migrations;
  IF v_history IS DISTINCT FROM v_manifest->'history' THEN RAISE EXCEPTION 'OWNER_ACL212_HISTORY_MISMATCH'; END IF;
  SET LOCAL search_path=public,pg_temp;
WITH namespaces AS (SELECT oid,nspname,nspowner,nspacl FROM pg_namespace
 WHERE nspname NOT LIKE 'pg_%' AND nspname<>'information_schema'),
relations AS (SELECT c.*,n.nspname FROM pg_class c JOIN namespaces n ON n.oid=c.relnamespace
 WHERE c.relkind IN ('r','p','v','m','f','S'))
SELECT jsonb_build_object(
 'schemas',(SELECT jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl) ORDER BY nspname) FROM namespaces),
 'tables',(SELECT jsonb_agg(jsonb_build_object('schema',r.nspname,'name',r.relname,'kind',r.relkind,
 'owner',pg_get_userbyid(r.relowner),'acl',r.relacl,'rls',r.relrowsecurity,'forceRls',r.relforcerowsecurity,
 'persistence',r.relpersistence,'options',r.reloptions,'replicaIdentity',r.relreplident,
 'partition',pg_get_expr(r.relpartbound,r.oid),
 'parents',COALESCE((SELECT jsonb_agg(jsonb_build_object('schema',pn.nspname,'name',pc.relname) ORDER BY pn.nspname,pc.relname)
 FROM pg_inherits inh JOIN pg_class pc ON pc.oid=inh.inhparent JOIN pg_namespace pn ON pn.oid=pc.relnamespace
 WHERE inh.inhrelid=r.oid),'[]'::jsonb),'view',CASE WHEN r.relkind IN('v','m') THEN pg_get_viewdef(r.oid,false) END,
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'number',a.attnum,'type',format_type(a.atttypid,a.atttypmod),
 'notNull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'acl',a.attacl,
 'collation',(SELECT collname FROM pg_collation WHERE oid=a.attcollation),
 'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum)
 FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
 WHERE a.attrelid=r.oid AND a.attnum>0 AND NOT a.attisdropped)) ORDER BY r.nspname,r.relname) FROM relations r),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',t.relname,'name',c.conname,'type',c.contype,
 'definition',pg_get_constraintdef(c.oid,false),'validated',c.convalidated,'deferrable',c.condeferrable,
 'initiallyDeferred',c.condeferred,'onUpdate',c.confupdtype,'onDelete',c.confdeltype,'match',c.confmatchtype,
 'local',c.conislocal,'noInherit',c.connoinherit,'inheritanceCount',c.coninhcount)
 ORDER BY n.nspname,t.relname,c.conname) FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN namespaces n ON n.oid=t.relnamespace),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',t.relname,'name',i.relname,
 'owner',pg_get_userbyid(i.relowner),'definition',pg_get_indexdef(i.oid),'valid',x.indisvalid,'ready',x.indisready,
 'primary',x.indisprimary,'unique',x.indisunique,'clustered',x.indisclustered,'replicaIdentity',x.indisreplident)
 ORDER BY n.nspname,t.relname,i.relname) FROM pg_index x JOIN pg_class i ON i.oid=x.indexrelid JOIN pg_class t ON t.oid=x.indrelid JOIN namespaces n ON n.oid=t.relnamespace),
 'functions',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'identity',p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',
 'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'configuration',p.proconfig,'kind',p.prokind,
 'definition',pg_get_functiondef(p.oid)) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid))
 FROM pg_proc p JOIN namespaces n ON n.oid=p.pronamespace WHERE p.prokind IN('f','w','p')),
 'policies',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',t.relname,'name',p.polname,'command',p.polcmd,
 'permissive',p.polpermissive,'roles',(SELECT jsonb_agg(CASE WHEN roleid=0 THEN 'PUBLIC' ELSE pg_get_userbyid(roleid) END ORDER BY roleid=0,pg_get_userbyid(roleid)) FROM unnest(p.polroles) roleid),
 'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY n.nspname,t.relname,p.polname)
 FROM pg_policy p JOIN pg_class t ON t.oid=p.polrelid JOIN namespaces n ON n.oid=t.relnamespace),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',t.relname,'name',g.tgname,
 'definition',pg_get_triggerdef(g.oid,false),'enabled',g.tgenabled) ORDER BY n.nspname,t.relname,g.tgname)
 FROM pg_trigger g JOIN pg_class t ON t.oid=g.tgrelid JOIN namespaces n ON n.oid=t.relnamespace WHERE NOT g.tgisinternal),
 'defaultPrivileges',(SELECT jsonb_agg(jsonb_build_object('role',pg_get_userbyid(d.defaclrole),'schema',COALESCE(n.nspname,''),'type',d.defaclobjtype,'acl',d.defaclacl)
 ORDER BY pg_get_userbyid(d.defaclrole),COALESCE(n.nspname,''),d.defaclobjtype) FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace),
 'sequences',(SELECT jsonb_agg(jsonb_build_object('schema',r.nspname,'name',r.relname,'start',s.seqstart,'increment',s.seqincrement,
 'max',s.seqmax,'min',s.seqmin,'cache',s.seqcache,'cycle',s.seqcycle) ORDER BY r.nspname,r.relname) FROM pg_sequence s JOIN relations r ON r.oid=s.seqrelid),
 'extensions',(SELECT jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname,'owner',pg_get_userbyid(e.extowner)) ORDER BY e.extname) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace)
) INTO v_catalog;
  SELECT count(*) INTO v_count FROM jsonb_array_elements(v_catalog->'functions') r WHERE r->>'schema'='public';
  IF v_count <> 556 THEN RAISE EXCEPTION 'OWNER_ACL212_FUNCTION_SCOPE_MISMATCH'; END IF;
  SELECT count(*) INTO v_count FROM jsonb_array_elements(v_catalog->'tables') r WHERE r->>'schema'='public';
  IF v_count <> 119 THEN RAISE EXCEPTION 'OWNER_ACL212_RELATION_SCOPE_MISMATCH'; END IF;
  FOREACH v_section IN ARRAY ARRAY['constraints','indexes','policies','triggers','sequences','defaultPrivileges','schemas'] LOOP
   -- Preserve exact bigint metadata; JSON/JavaScript numeric rounding is not
   -- an acceptable equivalence for a sequence boundary.
   SELECT coalesce(jsonb_agg(CASE WHEN v_section='sequences' THEN
    r||jsonb_build_object('start',r->>'start','increment',r->>'increment',
      'max',r->>'max','min',r->>'min','cache',r->>'cache') ELSE r END ORDER BY n),'[]'::jsonb) INTO v_related
    FROM jsonb_array_elements(v_catalog->v_section) WITH ORDINALITY AS e(r,n)
    WHERE CASE WHEN v_section='schemas' THEN r->>'name'='public' ELSE r->>'schema'='public' END;
   IF v_related IS DISTINCT FROM v_manifest->'related'->v_section THEN
    RAISE EXCEPTION 'OWNER_ACL212_RELATED_METADATA_MISMATCH: %',v_section;
   END IF;
  END LOOP;
  FOR v_object IN SELECT value FROM jsonb_array_elements(v_manifest->'objects') LOOP
   SELECT count(*),jsonb_agg(r)->0 INTO v_count,v_actual
    FROM jsonb_array_elements(v_catalog->(v_object->>'section')) r
    WHERE r->>'schema'='public' AND coalesce(r->>'identity',r->>'name')=v_object->>'identity';
   IF v_count<>1 THEN RAISE EXCEPTION 'OWNER_ACL212_IDENTITY_MISMATCH: %',v_object->>'key'; END IF;
   v_shape:=v_actual-'acl';
   IF v_object->>'section'='functions' THEN
    v_shape:=(v_shape-'definition')||jsonb_build_object('definitionMd5',md5(regexp_replace(v_actual->>'definition',E'\r+\n',E'\n','g')));
   END IF;
   IF v_shape IS DISTINCT FROM v_object->'shape' THEN
    RAISE EXCEPTION 'OWNER_ACL212_OWNER_CONFIG_OR_STRUCTURE_MISMATCH: %',v_object->>'key';
   END IF;
   SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',e.grantee_name,'grantor',e.grantor_name,
    'privilege',e.privilege_type,'grantable',e.is_grantable)
    ORDER BY e.grantee_name COLLATE "C",e.grantor_name COLLATE "C",e.privilege_type COLLATE "C"),'[]'::jsonb)
    INTO v_acl FROM (
     SELECT CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END AS grantee_name,
      pg_get_userbyid(x.grantor) AS grantor_name,x.privilege_type,x.is_grantable
     FROM aclexplode(ARRAY(SELECT jsonb_array_elements_text(
      CASE WHEN v_actual->'acl'='null'::jsonb THEN v_object->'defaultAcl' ELSE v_actual->'acl' END))::aclitem[]) x
    ) e;
   IF NOT (v_acl @> (v_object->'expectedAcl') AND ((v_object->'expectedAcl')||(v_object->'allowedExtra')) @> v_acl)
    OR (v_pass=2 AND v_acl IS DISTINCT FROM v_object->'expectedAcl') THEN
    RAISE EXCEPTION 'OWNER_ACL212_UNEXPECTED_ACL: %',v_object->>'key';
   END IF;
   IF v_pass=1 THEN
    v_before:=v_before||jsonb_build_object(v_object->>'key',jsonb_array_length(v_acl)-jsonb_array_length(v_object->'expectedAcl'));
   ELSE
    INSERT INTO pg_temp.owner_acl212_result VALUES(v_object->>'section',v_object->>'signature',
     v_actual->>'owner',v_actual->'configuration',v_acl,(v_before->>(v_object->>'key'))::integer,true);
   END IF;
  END LOOP;
  IF v_pass=1 THEN
   -- FIRST REVOKE: complete precondition has passed for every scoped object.
   REVOKE EXECUTE ON FUNCTION public._archive_supplier_receipt_impl(uuid,boolean) FROM service_role RESTRICT;
