   REVOKE EXECUTE ON FUNCTION public._create_product_with_opening_stock_impl(text,text,text,text,uuid,uuid,uuid,uuid,integer,bigint,bigint,bigint,integer,integer,uuid,integer,text) FROM service_role RESTRICT;
